import React, { useState, useEffect } from 'react';
import { createStackNavigator } from '@react-navigation/stack';
import LoginScreen from '../screens/LoginScreen';
import HomeScreen from '../screens/HomeScreen';
import ProductDetailScreen from '../screens/ProductDetailScreen';
import CartScreen from '../screens/CartScreen';
import { TouchableOpacity, Text, View, ActivityIndicator } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';

export type RootStackParamList = {
  Login: undefined;
  Home: undefined;
  ProductDetail: { productId: string };
  Cart: undefined;
};

const Stack = createStackNavigator<RootStackParamList>();

const AppNavigator = () => {
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    checkAuthStatus();
  }, []);

  const checkAuthStatus = async () => {
    try {
      const token = await AsyncStorage.getItem('auth_token');
      if (token) {
        setIsAuthenticated(true);
        // Set token in api header if needed
        // setAuthToken(token);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async (navigation: any) => {
     try {
       await AsyncStorage.removeItem('auth_token');
       setIsAuthenticated(false);
       // Optional: Navigate to login or just refresh state
       navigation.reset({
          index: 0,
          routes: [{ name: 'Home' }],
       });
     } catch(e) {
       console.error(e);
     }
  };

  if (loading) {
    return (
      <View style={{flex:1, justifyContent:'center', alignItems:'center'}}>
        <ActivityIndicator size="large" />
      </View>
    );
  }

  return (
    <Stack.Navigator initialRouteName="Home">
        <Stack.Screen 
          name="Home" 
          component={HomeScreen} 
          options={({ navigation }) => ({
            title: 'Menha Boutique',
            headerRight: () => (
              <View style={{flexDirection: 'row', alignItems: 'center'}}>
                 {isAuthenticated ? (
                    <TouchableOpacity onPress={() => handleLogout(navigation)} style={{ marginRight: 15 }}>
                      <Text style={{ color: 'red' }}>Logout</Text>
                    </TouchableOpacity>
                 ) : (
                    <TouchableOpacity onPress={() => navigation.navigate('Login')} style={{ marginRight: 15 }}>
                      <Text style={{ color: '#007AFF' }}>Login</Text>
                    </TouchableOpacity>
                 )}
                 <TouchableOpacity onPress={() => navigation.navigate('Cart')} style={{ marginRight: 15 }}>
                   <Text style={{ fontWeight: 'bold' }}>Cart</Text>
                 </TouchableOpacity>
              </View>
            ),
          })}
        />
        <Stack.Screen name="ProductDetail" component={ProductDetailScreen} options={{ title: 'Product Details' }} />
        <Stack.Screen name="Cart" component={CartScreen} options={{ title: 'Your Cart' }} />
        <Stack.Screen 
          name="Login" 
          component={LoginScreen} 
          options={{ title: 'Login' }} 
          initialParams={{ setIsAuthenticated }}
        />
    </Stack.Navigator>
  );
};

export default AppNavigator;
